  "The game draws with its own {d3d}.": "游戏使用自己的 {d3d} 绘制。",
  "In use: {provider} (DLSS5_MV_PROVIDER={value}).": "使用中：{provider}（DLSS5_MV_PROVIDER={value}）。",
